"""Write docs/parameters.md: every default parameter and its source."""

from pathlib import Path

import embodied_human as eh
from embodied_human.agents.driver import DriverAgentParameters


def main() -> int:
    human = eh.build_human()
    rows = human.provenance() + [
        {"category": "agents.driver", **row}
        for row in DriverAgentParameters().provenance()
    ]
    lines = [
        "# Parameters and their sources",
        "",
        "Generated by `python examples/parameter_table.py` from the code. Kinds:",
        "**measured** in humans, set by a **standard**, **fitted** to human data by",
        "the cited model, **derived** from other values, or **assumed** (a modelling",
        "choice to fit or replace).",
        "",
        "| Category | Parameter | Value | Kind | Source | Notes |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for row in rows:
        source = row["citation"]
        if row["doi"]:
            source = f"[{source}]({row['doi']})"
        lines.append(
            f"| {row['category']} | `{row['parameter']}` | {row['value']} "
            f"| {row['kind']} "
            f"| {source} | {row['note']} |"
        )
    counts = {}
    for row in rows:
        counts[row["kind"]] = counts.get(row["kind"], 0) + 1
    lines += [
        "",
        "Counts: " + ", ".join(f"{k} {v}" for k, v in sorted(counts.items())),
        "",
    ]
    Path("docs/parameters.md").write_text("\n".join(lines), encoding="utf-8")
    print(counts)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
